using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // 1. Discriminator: EF Core 9 renamed "Discriminator" → "$type".
        //    Preserve the old property name so existing documents are found.
        modelBuilder.Entity<Blog>()
            .HasDiscriminator<string>("Discriminator");

        // 2. Id format: EF Core 9 changed id from "Blog|{key}" → "{key}".
        //    Preserve the old format so existing documents are found.
        modelBuilder.Entity<Blog>()
            .HasPartitionKey(b => b.Id)
            .Property(b => b.Id)
            .ToJsonProperty("id");
        modelBuilder.Entity<Blog>()
            .UsePropertyAccessMode(PropertyAccessMode.Property);

        // 3. HasIndex: Cosmos provider now throws on HasIndex (was silently ignored).
        //    Removed the unsupported HasIndex call.

        // Raw-SQL note: any queries like
        //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
        // continue to work because we kept the old "Discriminator" property name above.
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Keep the legacy "EntityType|Key" id format for all entities
        configurationBuilder.Conventions.Add(_ =>
            new Microsoft.EntityFrameworkCore.Cosmos.Conventions.IdFormatConvention());
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

